prog='''def transform(grid):
    h, w = len(grid), len(grid[0])
    split, horiz = None, False
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and c == w - 1 - c:
            split = c; break
    if split is None:
        for r in range(h):
            if len({grid[r][c] for c in range(w)}) == 1 and r == h - 1 - r:
                split = r; horiz = True; break
    if horiz:
        A = [row[:] for row in grid[:split]]; B = [row[:] for row in grid[split+1:]]
        wl = len(A[0])
    else:
        A = [row[:split] for row in grid]; B = [row[split+1:] for row in grid]
        wl = split
    common = {x for row in A for x in row} & {x for row in B for x in row}
    bg = list(common)[0] if len(common) == 1 else 4
    return [[3 if A[r][c] == B[r][c] else bg for c in range(wl)] for r in range(len(A))]
'''
